        public static string DetectDefaultLanguage()
        {
            string language = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
            return String.Equals(language, "en", StringComparison.OrdinalIgnoreCase) ? "en-US" : "pt-BR";
        }

